/**
 * The replay seasons under tests/fixtures/seasons/, regenerated by
 * scripts/regenerate-replay-seasons.ts: three six-week fictional seasons that
 * are not marathon blocks (coaching-bias 25), then the hard-set seasons
 * (coaching-quality 04 and 05), whose hard weeks carry a `_note`. Checks the
 * committed packets say what the season scripts say, the exports regenerate
 * byte for byte, and the replay dry run over every packet passes the three
 * goal checks. Never calls the live model.
 */
import { execFileSync, spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdtempSync, readdirSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { assertPacketHasNoPiiOrGps } from "../src/packet/index.js";
import { PLAN_RULES } from "../src/prescribed/planCheck.js";
import type { ModelPacket } from "../src/packet/types.js";

const api = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const SEASONS = path.join(api, "tests/fixtures/seasons");
const PACKETS = path.join(SEASONS, "season-packets");
const GENERATOR = path.resolve(api, "../demo/generate-season-export.mjs");

type SeasonRun = { day: string; parts: unknown[] };
type SeasonWeek = { runs: SeasonRun[]; plan?: string; goal?: unknown; _note?: string };
type Season = { id: string; athlete: { name: string }; goal: unknown; aboutYou: string; weeks: SeasonWeek[] };
const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

const seasonFiles = readdirSync(SEASONS)
  .filter((f) => /^\d+-.+\.json$/.test(f))
  .sort();
const season = (stem: string) => JSON.parse(readFileSync(path.join(SEASONS, `${stem}.json`), "utf8")) as Season;
/** A season's packet names: the week padded to two digits in a season of ten weeks or more. */
const packetName = (stem: string, week: number) =>
  `${stem}-w${String(week).padStart(season(stem).weeks.length >= 10 ? 2 : 1, "0")}.json`;
const packet = (stem: string, week: number) =>
  JSON.parse(readFileSync(path.join(PACKETS, packetName(stem, week)), "utf8")) as ModelPacket;
const weeksOf = (stem: string) => season(stem).weeks.map((_, i) => i + 1);
const stems = seasonFiles.map((f) => f.replace(/\.json$/, ""));
/** The goal in force on a week's Sunday: the season's, or the last one a week saved before it. */
const goalAt = (s: Season, week: number) =>
  s.weeks.slice(0, week).reduce<unknown>((goal, w) => w.goal ?? goal, s.goal);
const sha256 = (file: string) => createHash("sha256").update(readFileSync(file)).digest("hex");

/** One section of the weekly report, from its heading to the next. */
function section(markdown: string, heading: string): string {
  const m = new RegExp(`^## ${heading}\\s*$([\\s\\S]*?)(?=^## |(?![\\s\\S]))`, "m").exec(markdown);
  return m?.[1] ?? "";
}

describe("replay seasons", () => {
  it("has the stay-fit, 10k and return seasons of six weeks, then the marathon build and the beginner's block, one weekly packet a week, in week order", () => {
    expect(seasonFiles).toEqual(["1-stay-fit.json", "2-10k.json", "3-return.json", "4-marathon.json", "5-beginner.json"]);
    for (const stem of ["1-stay-fit", "2-10k", "3-return"]) expect(season(stem).weeks).toHaveLength(6);
    expect(season("4-marathon").weeks).toHaveLength(14);
    expect(season("5-beginner").weeks).toHaveLength(8);
    const names = stems.flatMap((stem) => weeksOf(stem).map((w) => packetName(stem, w)));
    // File order is the replay's input order: seasons/01 is the first season's week 1.
    expect(readdirSync(PACKETS).sort()).toEqual(names);
    expect(names.indexOf("3-return-w6.json") + 1).toBe(18);
    expect(names.indexOf("4-marathon-w01.json") + 1).toBe(19);
    expect(names.indexOf("5-beginner-w1.json") + 1).toBe(33);
    expect(names).toHaveLength(40);
  });

  it.each(stems)(
    "every %s packet carries the goal, a short About you and a coaching block, and nothing identifying",
    (stem) => {
      const s = season(stem);
      for (const w of weeksOf(stem)) {
        const p = packet(stem, w);
        expect(p.goal).toEqual(goalAt(s, w));
        expect(p.coaching?.phase).toBeTruthy();
        // A goal changed in Settings reaches About you as a correction after the season's text.
        if (goalAt(s, w) === s.goal) expect(p.dossier?.body).toBe(s.aboutYou);
        else expect(p.dossier?.body.startsWith(`${s.aboutYou}\n\n## Athlete correction`)).toBe(true);
        expect(p.dossier!.body.length).toBeLessThan(700);
        expect(p.recapMarkdown).toContain("## Run-by-run");
        expect(p.planWeek).toBeTruthy();
        const text = JSON.stringify(p);
        for (const part of s.athlete.name.split(" ")) expect(text).not.toContain(part);
        assertPacketHasNoPiiOrGps(p, { forbiddenSubstrings: ["LineString", "rawGpxData", "rawFitData"] });
      }
    },
  );

  it.each(stems)(
    "every %s packet from week 2 carries the week's plan with each day's outcome; week 1 carries null for both (#59)",
    (stem) => {
      const s = season(stem);
      const first = packet(stem, 1);
      expect(first).toHaveProperty("prescribedWeek", null);
      expect(first).toHaveProperty("prescribedWeekOutcomes", null);
      for (const w of weeksOf(stem).slice(1)) {
        const p = packet(stem, w);
        const week = s.weeks[w - 1]!;
        expect(p.prescribedWeek?.week).toBe(p.week?.isoWeek);
        expect(p.prescribedWeek?.days).toHaveLength(7);
        const outcomes = p.prescribedWeekOutcomes!;
        expect(outcomes.map((d) => d.date)).toEqual(p.prescribedWeek!.days.map((d) => d.date));
        const runDays = new Set(week.runs.map((r) => r.day));
        outcomes.forEach((d, i) => expect(d.actualDistanceM! > 0).toBe(runDays.has(DAYS[i]!)));
        if (week.plan === undefined) {
          // The plan the stub was given for this week is the week's scripted runs:
          // every planned day is done and the rest are rest.
          expect(outcomes.map((d) => d.state)).toEqual(DAYS.map((d) => (runDays.has(d) ? "done" : "rest")));
        } else {
          // The week's own plan lines, as the parser filed them; a planned run not run is missed.
          expect(p.prescribedWeek!.days.map((d) => d.line)).toEqual(week.plan.split("\n"));
          p.prescribedWeek!.days.forEach((d, i) => {
            if (d.run && !runDays.has(DAYS[i]!)) expect(outcomes[i]!.state).toBe("missed");
          });
        }
      }
    },
  );

  it("the marathon's overrun week packet shows a 38 mi plan against 53 mi run, day by day", () => {
    const p = packet("4-marathon", 8);
    const mi = (m: number) => Math.round(m / 1609.344);
    const planned = p.prescribedWeek!.days.reduce((a, d) => a + (d.run?.distanceM ?? 0), 0);
    const run = p.prescribedWeekOutcomes!.reduce((a, d) => a + (d.actualDistanceM ?? 0), 0);
    expect([mi(planned), mi(run)]).toEqual([38, 53]);
    // Monday was a rest day and was run; Sunday's 15 mi long run was run as 20.
    expect(p.prescribedWeek!.days[0]).toMatchObject({ dayType: "rest", run: null });
    expect(p.prescribedWeekOutcomes![0]).toMatchObject({ state: "done" });
    expect(mi(p.prescribedWeek!.days[6]!.run!.distanceM)).toBe(15);
    expect(mi(p.prescribedWeekOutcomes![6]!.actualDistanceM!)).toBe(20);
    expect(p.recapMarkdown).toContain("| Distance | 53.0");
  });

  it("the marathon's race-moved week carries the new race date, saved that Sunday, and the weeks before the old one", () => {
    expect(packet("4-marathon", 9).goal).toMatchObject({ raceDate: "2026-11-01" });
    for (const w of [10, 11, 12, 13, 14]) expect(packet("4-marathon", w).goal).toMatchObject({ raceDate: "2026-10-18" });
    expect(packet("4-marathon", 10).dossier!.body).toContain("My goal is now race: Wexley Lakes Marathon on Sun Oct 18 2026");
  });

  it.each(stems)("every hard week of %s says its scenario and names the plan rules a careless plan would trip", (stem) => {
    for (const week of season(stem).weeks) {
      if (week._note === undefined) continue;
      expect(week._note).toMatch(/^Hard week \([^)]+\): /);
      const named = PLAN_RULES.filter((rule) => week._note!.includes(rule));
      expect(named.length > 0 || /\bno rule\b/i.test(week._note), week._note).toBe(true);
    }
  });

  it.each([
    ["4-marathon", [4, 6, 8, 9, 10, 12, 13, 14]],
    ["5-beginner", [1, 3, 5, 8]],
    ["3-return", [1]],
  ] as const)("%s has its hard weeks at %j, and no note reaches a packet", (stem, weeks) => {
    const hard = season(stem).weeks.flatMap((w, i) => (w._note ? [i + 1] : []));
    expect(hard).toEqual(weeks);
    for (const w of weeksOf(stem)) expect(JSON.stringify(packet(stem, w))).not.toContain("Hard week");
  });

  it("the beginner's weeks of nothing run carry the plan they were given, every planned day missed", () => {
    for (const w of [5, 7, 8]) {
      const p = packet("5-beginner", w);
      expect(season("5-beginner").weeks[w - 1]!.runs).toEqual([]);
      const planned = p.prescribedWeek!.days.map((d) => (d.run ? DAYS[p.prescribedWeek!.days.indexOf(d)] : null)).filter(Boolean);
      expect(planned).toEqual(["Mon", "Wed", "Sat"]);
      expect(p.prescribedWeekOutcomes!.map((d) => d.state)).toEqual(["missed", "rest", "missed", "rest", "rest", "missed", "rest"]);
      expect(p.recapMarkdown).toContain("| Distance | 0.00 km");
    }
    // The ill week: Monday run, the other two missed.
    expect(packet("5-beginner", 3).prescribedWeekOutcomes!.map((d) => d.state)).toEqual(["done", "rest", "missed", "rest", "rest", "missed", "rest"]);
  });

  it("the 10k season's week 4 report shows the parkrun 5K best on the new-bests line", () => {
    const notable = section(packet("2-10k", 4).recapMarkdown!, "Notable");
    expect(notable).toMatch(/^- New best: 5K 21:\d\d \(was 21:55\)$/m);
    for (const w of [1, 2, 3]) expect(packet("2-10k", w).recapMarkdown).not.toContain("New best");
  });

  it("the return season's week 3 report has the one pain score", () => {
    const md = packet("3-return", 3).recapMarkdown!;
    expect(md).toContain("Pain: 3/10 (Left shin ached");
    expect(section(md, "Subjective recap")).toContain("Pain: highest 3/10 (Wed)");
    for (const w of [1, 2, 4, 5, 6]) {
      expect(packet("3-return", w).recapMarkdown).not.toMatch(/Pain: highest [1-9]/);
    }
  });

  it("the exports regenerate byte for byte from the season scripts", () => {
    const out = mkdtempSync(path.join(tmpdir(), "season-export-"));
    for (const f of seasonFiles) {
      const zip = path.join(out, f.replace(/\.json$/, ".zip"));
      execFileSync("node", [GENERATOR, "--season", path.join(SEASONS, f), "--out", zip], { stdio: "ignore" });
      expect(sha256(zip)).toBe(sha256(path.join(SEASONS, f.replace(/\.json$/, ".zip"))));
    }
  }, 30_000);

  it("the replay dry run over every season passes the three goal checks", () => {
    const out = mkdtempSync(path.join(tmpdir(), "replay-seasons-"));
    const env = { ...process.env };
    delete env.ANTHROPIC_API_KEY;
    const run = spawnSync(
      path.join(api, "node_modules/.bin/tsx"),
      ["scripts/replay-weekly-reads.ts", "--packets", PACKETS, "--dry-run", "--out", out],
      { cwd: api, env, encoding: "utf8" },
    );
    expect(run.stderr).toBe("");
    expect(run.status).toBe(0);
    const report = readFileSync(path.join(out, "report.md"), "utf8");
    const files = readdirSync(PACKETS).sort();
    expect(report).toContain(`from ${files.length} replayed coach calls`);
    expect(report).toMatch(/## Goal checks\n\nAll passed/);
    expect(report).toContain("### 18.1 (3-return-w6.json)");
    expect(report).toContain(`### ${files.length}.1 (${files.at(-1)})`);
  }, 60_000);
});
